const PERFORMANCE_TESTS={AS1:['PRODUCTIVIDAD','SELECTIVIDAD','ESPECIFICIDAD'],AC1:['PRODUCTIVIDAD','SELECTIVIDAD','ESPECIFICIDAD'],LMX:['PRODUCTIVIDAD','SELECTIVIDAD','ESPECIFICIDAD'],AN:[],PDA:['PRODUCTIVIDAD'],PCA:['PRODUCTIVIDAD'],EMB:['PRODUCTIVIDAD'],BHI:['PRODUCTIVIDAD']};
