const calculationModes=(p,t)=>{
 if(t==='ESPECIFICIDAD'||p.type==='Caldo')return ['CUALITATIVO'];
 if(t==='PRODUCTIVIDAD')return ['CUALITATIVO','PR'];
 if(t==='SELECTIVIDAD')return ['CUALITATIVO','SF'];
 return ['CUALITATIVO'];
};
const recommendedMode=(p,t)=>p.mediumId==='PCA'&&t==='PRODUCTIVIDAD'?'PR':'CUALITATIVO';
const referenceSuggestion=(p,t)=>p.type==='Caldo'
 ?'Control positivo y negativo del método (identificar lotes en observaciones)'
 :t==='PRODUCTIVIDAD'?'Medio no selectivo de referencia: identificar nombre y lote'
 :t==='SELECTIVIDAD'?'Control no selectivo de referencia: identificar nombre y lote'
 :'Control positivo/negativo de reacción característica';
const calcResult=(mode,n0,ns,limit)=>{
 const a=Number(n0),b=Number(ns),l=Number(limit);
 if(mode==='CUALITATIVO')return {value:null,valid:true};
 if(n0===''||ns===''||limit===''||!Number.isFinite(a)||!Number.isFinite(b)||!Number.isFinite(l)||a<=0||b<0||l<0)return {valid:false,reason:'Registre recuentos válidos y el límite aprobado por Calidad.'};
 if(mode==='PR')return {valid:true,value:b/a,pass:b/a>=l,formula:'PR = Ns / N₀'};
 if(mode==='SF'){
  if(b===0)return {valid:false,reason:'Ns = 0: indique el límite de detección; log₁₀(0) no está definido.'};
  return {valid:true,value:Math.log10(a)-Math.log10(b),pass:Math.log10(a)-Math.log10(b)>=l,formula:'SF = log₁₀(N₀) − log₁₀(Ns)'};
 }
 return {valid:false,reason:'Modo no admitido'};
};
const quantitativeHtml=(t,prev,p)=>{
 const modes=calculationModes(p,t),mode=modes.includes(prev.mode)?prev.mode:recommendedMode(p,t);
 const liquid=p.type==='Caldo';
 return `<div class="media-qc-panel"><div class="media-summary"><strong>Evaluación ${H(t.toLowerCase())} · ${liquid?'medio líquido':'medio sólido'}</strong><br>${liquid?'Evaluación cualitativa de respuestas observadas; no se solicitan UFC de placas ni PR/SF.':'La evaluación cuantitativa requiere recuentos comparables, medio de referencia identificado y criterio aprobado.'}</div><div class="media-qc-grid"><label>Modelo aplicable<select name="mode_${t}">${modes.map(m=>`<option value="${m}" ${m===mode?'selected':''}>${m==='CUALITATIVO'?'Cualitativo · respuesta esperada':m==='PR'?'PR · productividad cuantitativa':'SF · selectividad cuantitativa'}</option>`).join('')}</select></label><label>Medio / control de referencia<input name="reference_${t}" value="${H(prev.reference||referenceSuggestion(p,t))}" maxlength="160" required><small>${liquid?'Identifique los controles realmente empleados; no equivale a un recuento UFC.':'Indique medio y lote real de referencia cuando se usen recuentos.'}</small></label><label>Fuente documental del criterio<input name="source_${t}" value="${H(prev.source||'')}" placeholder="Procedimiento PSI (código/revisión) y ficha técnica del fabricante" maxlength="180" required><small>ISO 11133 es marco general; registre la fuente específica aprobada.</small></label></div><div data-quant-fields="${t}" ${mode==='CUALITATIVO'?'hidden':''}><div class="media-qc-grid"><label>N₀ · colonias en medio de referencia<input type="number" name="n0_${t}" min="0" step="any" value="${H(prev.n0??'')}" placeholder="Recuento de placa de referencia"></label><label>Ns · colonias en lote evaluado<input type="number" name="ns_${t}" min="0" step="any" value="${H(prev.ns??'')}" placeholder="Recuento de placa del lote"></label><label>Límite mínimo aprobado<input type="number" name="limit_${t}" min="0" step="any" value="${H(prev.limit??'')}" placeholder="Criterio autorizado por PSI"><small>Sin criterio aprobado no se calcula conformidad cuantitativa.</small></label></div></div><div class="media-summary" data-calculation="${t}">Complete los resultados y la fuente documental.</div></div>`;
};

