const QC_SPEC={
 AS1:{ph:[6.7,7.1],color:'Amarillento',appearance:'Transparente a ligeramente opalescente',preparedStorage:'Temperatura ambiente, protegido de la luz; máximo 7 días',commercialStorage:'15–25 °C'},
 AC1:{ph:[6.7,7.1],color:'Amarillento',appearance:'Transparente a ligeramente opalescente',preparedStorage:'Temperatura ambiente, protegido de la luz; máximo 7 días',commercialStorage:'15–25 °C'},
 LMX:{ph:[6.6,7.0],color:'Marrón amarillento',appearance:'Claro',preparedStorage:'2–8 °C',commercialStorage:'15–25 °C'},
 PDA:{ph:[5.4,5.8],color:'Amarillo claro',appearance:'Gel transparente a ligeramente opalescente',preparedStorage:'2–8 °C',commercialStorage:'2–25 °C'},
 PCA:{ph:[6.8,7.2],color:'Amarillo claro',appearance:'Gel transparente a ligeramente opalescente',preparedStorage:'2–8 °C',commercialStorage:'10–25 °C'},
 EMB:{ph:[6.9,7.3],color:'Púrpura rojizo con ligero matiz anaranjado',appearance:'Transparente',preparedStorage:'2–8 °C',commercialStorage:'2–30 °C'},
 AN:{ph:[7.2,7.6],color:'Amarillo claro',appearance:'Gel transparente a ligeramente opalescente',preparedStorage:'2–8 °C',commercialStorage:'2–30 °C'},
 BHI:{ph:[7.2,7.6],color:'Ámbar claro',appearance:'Según ficha técnica del fabricante',preparedStorage:'2–8 °C',commercialStorage:'10–25 °C'}
};
const qcRange=p=>p.qcLimitsApplied?.min!=null&&p.qcLimitsApplied?.max!=null?[p.qcLimitsApplied.min,p.qcLimitsApplied.max]:QC_SPEC[p.mediumId]?.ph||null;
const qcResponsible=p=>p.qcEvaluatedByCode||(p.qcEvaluatedBy===user?.uid?profile?.userCode:null)||(p.qcEvaluatedBy===p.actorUid?p.actorCode:null)||profile?.userCode||'No identificado';
const QC_DESCRIPTIONS=Object.fromEntries(Object.entries(QC_SPEC).map(([id,spec])=>[id,spec]));
