const qcStatus=p=>{const fields=['noTurbidity','noMicroorganisms','sterility','appearance'];if(fields.some(k=>p[k]==='NO_CUMPLE'))return 'NO APTO';const range=qcRange(p);if(p.measuredPh!==null&&p.measuredPh!==undefined&&range&&(Number(p.measuredPh)<range[0]||Number(p.measuredPh)>range[1]))return 'NO APTO';if(!range||!Number.isFinite(Number(p.measuredPh))||p.measuredPh===null||p.measuredPh===undefined||fields.some(k=>!p[k]))return 'INCOMPLETO';return 'APTO';};
