// Política central de cobertura: misma formulación y frasco comercial.
// AS1/AC1 constituyen una única familia documental expresamente compartida.
// No se extiende la cobertura entre formulaciones diferentes por defecto.
const performanceFamily=id=>['AS1','AC1'].includes(id)?'A1':String(id||'');
const samePerformanceFamily=(a,b)=>performanceFamily(a)===performanceFamily(b);
const completePerformanceEvidence=p=>p.performanceResults&&requiredTests(p).length>0&&requiredTests(p).every(t=>p.performanceResults[t]&&(p.performanceResults[t].result==='CONFORME'||p.performanceResults[t].conclusion==='CONFORME'));
const performanceCoverage=target=>{
 if(!target?.lotId||!target.mediumId)return null;
 return preps.filter(source=>source.id!==target.id&&source.lotId===target.lotId
  &&samePerformanceFamily(source.mediumId,target.mediumId)
  &&source.performance==='CONFORME'&&source.qc==='CONFORME'
  &&['LIBERADO','LIBERADO_HISTORICO','CERRADO','BAJA'].includes(source.status)
  &&source.date<=target.date&&completePerformanceEvidence(source))
  .sort((a,b)=>String(a.date).localeCompare(String(b.date)))[0]||null;
};
const bottlePerformanceSource=(r,l,preparedDate)=>preps.filter(x=>x.lotId===l.id&&samePerformanceFamily(x.mediumId,r.prefix)&&x.performance==='CONFORME'&&x.qc==='CONFORME'&&['LIBERADO','LIBERADO_HISTORICO','CERRADO','BAJA'].includes(x.status)&&completePerformanceEvidence(x)&&(!preparedDate||x.date<=preparedDate)).sort((a,b)=>String(a.date).localeCompare(String(b.date)))[0]||null;
