 const button=f.querySelector('button[type="submit"]');
 const report=(text,isError=true)=>{let el=f.querySelector('[data-qc-feedback]');if(!el){el=document.createElement('div');el.dataset.qcFeedback='';el.setAttribute('role','status');el.className='media-summary';button?.before(el);}el.textContent=text;el.style.borderLeft=`4px solid ${isError?'#c2410c':'#08765e'}`;el.scrollIntoView({block:'nearest',behavior:'smooth'});};
 if(!p){report('No se encontró el lote seleccionado. Actualice la lista.');return;}
 const correction=qcCorrectionId===id&&profile.role==='ADMIN';
 if((p.status!=='PENDIENTE'||p.qc!=='PENDIENTE')&&!correction){report('Este QC ya fue evaluado; consulte el historial.');return;}
 const reason=correction?f.elements.correctionReason?.value.trim():'';
 if(correction&&(!reason||reason.length<10||reason.length>500)){report('Indique un motivo de rectificación de 10 a 500 caracteres.');return;}
 const evaluationDate=f.elements.evaluationDate.value;
 if(!/^\d{4}-\d{2}-\d{2}$/.test(evaluationDate)||evaluationDate<p.date||evaluationDate>p.expiry){report(`La fecha QC debe estar entre ${p.date} y ${p.expiry}.`);return;}
